import {canRecords,esc,day,localDateTime,dateTimeToISO,number,statusLabels,permissionLabels,validateDocument,invitationMail,code} from './records-model.js';
export function createRecordsModule(baseStore,logo){
 let api,root,lang='es',profile,boot=null,mode='documents',rows=[],parties=[],suppliers=[],adminData=null,doc=null,draft=null,dirty=false,busy=false,error='',notice='',q='',status='',offset=0,partyBack=false,adminTab='units',editing=null;
 let writing=false,view='all',total=0,returnView=null,restoreScroll=null,previewDialog=null,previewUrl='';
 let draftCount=0,exitPending=false,choosingSigner=false,pendingAttachments=[],memberSiteFilter='';
 let direction='incoming',filters={},filterCache={},filterPeople=[],intakeFile=null,intakePreview='',intakePages=0,intakeUploaded=false;
 const t=(es,en)=>lang==='es'?es:en,can=p=>canRecords(boot,p),b=(act,text,primary=false,attrs='')=>`<button type="button" class="${primary?'primary':'secondary'}" data-records="${act}" ${attrs}>${esc(text)}</button>`,opt=(value,text,selected)=>`<option value="${esc(value)}" ${String(value)===String(selected)?'selected':''}>${esc(text)}</option>`,labelStatus=s=>recordStatus(s,doc?.direction||direction,lang),fmt=v=>v?new Intl.DateTimeFormat(lang==='es'?'es-EC':'en-GB',{dateStyle:'medium',timeStyle:'short',timeZone:'Pacific/Galapagos'}).format(new Date(v)):'—';
 const input=(name,label,value='',attrs='')=>`<label>${esc(label)}<input name="${name}" value="${esc(value)}" ${attrs}></label>`;
 const select=(name,label,html)=>`<label>${esc(label)}<select name="${name}">${html}</select></label>`;
 const blank=t('Seleccione','Select'),pick=()=>opt('',blank,''),statusBadge=s=>`<span class="badge ${['sent','signed','closed'].includes(s)?'green':'gray'}">${esc(labelStatus(s))}</span>`;
 function message(e){const m=String(e?.message||e);if(m.includes('REASON_REQUIRED'))return t('Describa la disposición o la atención realizada (entre 5 y 3000 caracteres).','Describe the instruction or action taken (5–3000 characters).');if(m.includes('INVALID_ASSIGNEE'))return t('Seleccione un responsable activo.','Select an active owner.');if(m.includes('INVALID_EVIDENCE'))return t('Seleccione un documento de este oficio.','Select a file belonging to this letter.');if(m.includes('DUPLICATE_ATTACHMENT'))return t('Ya hay un anexo con ese nombre. Revise los archivos o cambie el nombre antes de agregarlo.','An attachment with that name already exists. Review the files or rename it before adding.');if(m.includes('ENCRYPTED_PDF'))return t('El PDF está protegido. Suba una copia sin contraseña.','The PDF is encrypted. Upload a copy without a password.');if(m.includes('INVALID_PDF'))return t('No se pudo leer el PDF. Compruebe que esté completo y vuelva a exportarlo o escanearlo.','Unable to read the PDF. Check that it is complete and export or scan it again.');if(m.includes('REPLACEMENT_REASON'))return t('Indique el motivo para incorporar una nueva versión del oficio.','Enter a reason for adding a new version.');return m.includes('glf_records')&&(m.includes('find')||e?.code==='PGRST202')?t('El módulo necesita activar su migración de base de datos. Los demás módulos siguen disponibles.','This module requires its database migration. Other modules remain available.'):m.includes('MEMBER_REQUIRED')?t('Falta asignar su dirección, sede y cargo en Administración.','Assign your unit, site and job title in Administration first.'):m.includes('ORIGIN_CHANGED')?t('Cambió la dirección, sede o perfil de quien redactó. Devuelva el oficio para revisar y guardar su origen antes de aprobarlo.','The author’s unit, site or profile changed. Return the letter to review and save its origin before approval.'):m.includes('STALE')?t('El registro cambió. Vuelva a abrirlo antes de guardar.','The record changed. Reopen it before saving.'):m.includes('FORBIDDEN')?t('Su cuenta no tiene permiso para esta acción o el estado del oficio no la permite.','Your account or the letter state does not allow this action.'):m.includes('duplicate')||m.includes('DUPLICATE')?t('Ya existe ese nombre, sigla o combinación de iniciales. Revise el registro existente.','This name, code or initials combination already exists.'):m.includes('FILE')?t('Revise el archivo: PDF, o Word DOCX como original; máximo 20 MB.','Check the file: PDF, or Word DOCX as source; maximum 20 MB.'):t('No se pudo completar. Revise los datos, la conexión y los permisos.','Unable to complete. Check your data, connection and permissions.');}
 async function run(fn){if(busy)return;busy=true;error='';draw();try{await fn();return true;}catch(e){error=message(e);return false;}finally{busy=false;draw();}}
 async function refresh(){
  if(!boot||mode==='admin')boot=await api.rpc('bootstrap');
  if(mode==='admin')adminData=await api.rpc('admin');
  else if(mode==='documents'){
   const [result,people]=await Promise.all([api.rpc('list',null,null,{q,status,offset,direction,view,...filters}),api.rpc('filter_people')]);
   rows=result.rows;total=result.total??rows.length;draftCount=result.draft_count||0;filterPeople=people;
   if(offset&&offset>=total){offset=Math.max(0,Math.floor((total-1)/50)*50);const last=await api.rpc('list',null,null,{q,status,offset,direction,view,...filters});rows=last.rows;total=last.total??rows.length;}
  }else if(mode==='contacts')parties=await api.rpc('parties',null,null,{q,offset});
  else if(doc&&!draft)doc=await api.rpc('read',doc.id);
 }
 function rememberList(){if(mode==='documents'){const state={direction,view,q,status,offset,filters:{...filters},scroll:window.scrollY};filterCache[workspaceKey(direction,view)]=state;returnView=state;}}
 function restoreList(state){direction=state.direction;view=state.view;q=state.q;status=state.status;offset=state.offset;filters={...state.filters};restoreScroll=state.scroll||0;}
 function sidebar(){return '<aside class="records-sidebar"><nav aria-label="'+t('Bandejas de correspondencia','Correspondence trays')+'">'+['incoming','outgoing'].map(dir=>'<section><button type="button" class="records-group" data-records="'+(dir==='incoming'?'inbox':'outbox')+'">'+t(dir==='incoming'?'Oficios recibidos':'Oficios de salida',dir==='incoming'?'Incoming letters':'Outgoing letters')+'</button>'+b(dir==='incoming'?'incoming':'new',t(dir==='incoming'?'Registrar recibido':'Crear oficio',dir==='incoming'?'Register incoming':'Create letter'),true,can(dir==='incoming'?'receive':'create')?'':'disabled title="'+t('Sin permiso asignado','Permission not assigned')+'"')+recordViews[dir].map(([key,es,en])=>b('tray',t(es,en)+(key==='drafts'?' ('+draftCount+')':''),false,'data-id="'+dir+':'+key+'" '+(mode==='documents'&&direction===dir&&view===key?'aria-current="page"':''))).join('')+'</section>').join('')+b('contacts',t('Instituciones y contactos','Institutions and contacts'),false,mode==='contacts'?'aria-current="page"':'')+'</nav></aside>';}
 function closePreview(){previewDialog?.close();previewDialog?.remove();previewDialog=null;if(previewUrl)URL.revokeObjectURL(previewUrl);previewUrl='';}
 async function showPreview(blob,name){
  closePreview();previewUrl=URL.createObjectURL(blob);const focus=document.activeElement;
  previewDialog=document.createElement('dialog');previewDialog.className='records-pdf-dialog';
  previewDialog.innerHTML='<div class="records-preview-bar"><h2>'+esc(t('Vista previa','Preview'))+'</h2><a class="button secondary" href="'+previewUrl+'" download="'+esc(name)+'">'+t('Descargar PDF','Download PDF')+'</a><button type="button" class="secondary" data-close-preview>'+t('Cerrar vista previa','Close preview')+'</button></div><p>'+esc(name)+'</p><div class="records-pdf-viewer" aria-label="'+t('Vista previa del oficio PDF','Letter PDF preview')+'"></div><p class="records-help">'+t('Si su navegador no muestra el PDF, utilice Descargar PDF.','If your browser cannot display the PDF, use Download PDF.')+'</p>';
  document.body.append(previewDialog);const dialog=previewDialog;dialog.querySelector('[data-close-preview]').onclick=()=>dialog.close();dialog.onclose=()=>{if(previewDialog===dialog){URL.revokeObjectURL(previewUrl);previewUrl='';previewDialog=null;}dialog.remove();if(focus?.isConnected)focus.focus();};dialog.showModal();
  const {renderPdfPreview}=await import('./records-pdf-preview.js');if(dialog.open)await renderPdfPreview(dialog.querySelector('.records-pdf-viewer'),blob,lang);
 }
 function snapshotDraft(){const signer=boot.signers.find(x=>x.id===draft.signer_id);return {...draft,signer_name:signer?.name,job_title:signer?.job_title,author_name:profile.display_name,origin_code:code(boot.units.find(u=>u.id===boot.member?.unit_id)?.code,boot.sites.find(s=>s.id===boot.member?.site_id)?.code,boot.member?.initials),recipients:draft.recipients.filter(r=>r.party_id).map(r=>({...r,party:parties.find(p=>p.id===r.party_id),contact:parties.find(p=>p.id===r.party_id)?.contacts?.find(c=>c.id===r.contact_id)})),attachments:[...recordAttachments(draft),...pendingAttachments.map(f=>({filename:f.name}))]};}
 async function leave(){
  if(busy||exitPending)return false;if(!dirty)return true;
  if(mode!=='edit'||draft?.direction!=='outgoing')return confirm(t('Hay cambios sin guardar. ¿Desea salir?','There are unsaved changes. Leave?'));
  exitPending=true;const choice=await chooseDraftExit(lang);exitPending=false;
  if(choice==='stay')return false;
  if(choice==='save')return saveOutgoing();
  dirty=false;pendingAttachments=[];draft=null;mode=doc?'detail':'documents';return true;
 }
 async function saveOutgoing(){
  const newlyCreated=!draft.id;collect();if(!draft.document_date)draft.document_date=day();
  const errors=validateDocument(draft);if(errors.length){showErrors(root.querySelector('#record-editor'),errors);return false;}
  return run(async()=>{
   const data={...draft,recipients:draft.recipients.filter(r=>r.party_id)};
   const id=await api.rpc('save',draft.id||null,draft.version||null,data);
   draft.id=id;draft.version=(draft.version||0)+1;
   doc=await api.rpc('read',id);draft.version=doc.version;
   while(pendingAttachments.length){
    const file=pendingAttachments[0];
    if(!doc.files.some(f=>f.kind==='attachment'&&f.filename===file.name&&f.size===file.size)){
     notice=t('Subiendo anexo: ','Uploading attachment: ')+file.name;draw();
     await api.upload(doc,file,'attachment');doc=await api.rpc('read',id);draft.version=doc.version;
    }
    pendingAttachments.shift();draft.files=doc.files;
   }
   if(newlyCreated)draftCount++;dirty=false;draft=null;choosingSigner=false;mode='detail';
   notice=t('Borrador guardado · ','Draft saved · ')+fmt(doc.updated_at)+t(' (Galápagos). Puede retomarlo en Oficios de salida → Borradores.',' (Galápagos). Resume it in Outgoing letters → Drafts.');
  });
 }
 window.addEventListener('beforeunload',ev=>{if(dirty&&root?.isConnected){ev.preventDefault();ev.returnValue='';}});
 async function chooseParty(){
  const dialog=document.createElement('dialog');dialog.className='records-party-dialog';let searchOffset=0,term='',generation=0;
  dialog.innerHTML='<h2>'+t(draft.direction==='incoming'?'Buscar remitente':'Buscar destinatario',draft.direction==='incoming'?'Search sender':'Search recipient')+'</h2><form class="records-toolbar"><label>'+t('Institución, persona o correo','Institution, person or email')+'<input name="party_query" maxlength="200" autofocus></label><button class="primary">'+t('Buscar','Search')+'</button></form><div class="records-party-results" aria-live="polite"></div><div class="records-actions"><button type="button" class="secondary" data-party-prev>'+t('Anterior','Previous')+'</button><button type="button" class="secondary" data-party-next>'+t('Siguiente','Next')+'</button><button type="button" class="secondary" data-party-close>'+t('Cerrar','Close')+'</button></div>';
  document.body.append(dialog);dialog.onclose=()=>{generation++;dialog.remove();root.querySelector('[data-records="choose-party"]')?.focus();};dialog.querySelector('[data-party-close]').onclick=()=>dialog.close();
  async function search(){const request=++generation,results=dialog.querySelector('.records-party-results');results.textContent=t('Buscando…','Searching…');dialog.querySelectorAll('[data-party-prev],[data-party-next]').forEach(b=>b.disabled=true);
   try{const found=await api.rpc('parties',null,null,{q:term,offset:searchOffset});if(!dialog.isConnected||request!==generation)return;
    results.innerHTML=found.map(p=>'<div class="records-party-result"><div><strong>'+esc(p.name)+'</strong><small>'+esc(p.address||'')+'</small><small>'+esc(p.email||p.contacts?.[0]?.email||'')+'</small></div><button type="button" class="secondary" data-pick-party="'+esc(p.id)+'">'+t('Seleccionar','Select')+'</button></div>').join('')||'<p>'+t('No hay coincidencias. Puede cerrar y registrar o vincular una contraparte.','No matches. Close this search to register or link a correspondent.')+'</p>';
    dialog.querySelector('[data-party-prev]').disabled=searchOffset===0;dialog.querySelector('[data-party-next]').disabled=found.length<50;
    results.querySelectorAll('[data-pick-party]').forEach(button=>button.onclick=()=>{const p=found.find(x=>x.id===button.dataset.pickParty);if(!parties.some(x=>x.id===p.id))parties.push(p);const empty=draft.recipients.find(r=>!r.party_id);if(empty)Object.assign(empty,{party_id:p.id,contact_id:null});else if(!draft.recipients.some(r=>r.party_id===p.id))draft.recipients.push({party_id:p.id,contact_id:null,kind:draft.direction==='incoming'?'from':'to'});dirty=true;dialog.close();draw();root.querySelector('[data-records="choose-party"]')?.focus();});
   }catch(e){if(request===generation&&dialog.isConnected)results.textContent=message(e);}
  }
  dialog.querySelector('form').onsubmit=ev=>{ev.preventDefault();term=dialog.querySelector('[name=party_query]').value;searchOffset=0;search();};dialog.querySelector('[data-party-prev]').onclick=()=>{searchOffset=Math.max(0,searchOffset-50);search();};dialog.querySelector('[data-party-next]').onclick=()=>{searchOffset+=50;search();};dialog.showModal();await search();
 }
 function title(){return mode==='admin'?t('Direcciones, sedes y perfiles','Units, sites and roles'):t('Correspondencia y archivo','Correspondence and archive');}
 function draw(){if(!root)return;
 const content=!boot?'<section class="panel">'+(error?b('retry',t('Reintentar','Retry')):t('Cargando…','Loading…'))+'</section>':mode==='admin'?adminView():mode==='edit'?editor():mode==='detail'?detail():mode==='party'?partyForm():mode==='contacts'?contactsView():listView();
 const notices='<p class="error records-error" role="alert">'+esc(error)+'</p>'+(notice?'<p role="status" class="records-note">'+esc(notice)+'</p>':'');
 root.innerHTML='<header class="records-heading"><h1>'+title()+'</h1></header>'+(boot&&mode!=='admin'?'<div class="records-workspace">'+sidebar()+'<div class="records-workspace-content">'+notices+content+'</div></div>':notices+content);
 if(restoreScroll!==null&&!busy){const y=restoreScroll;restoreScroll=null;requestAnimationFrame(()=>window.scrollTo(0,y));}
 root.querySelectorAll('[data-record-anchor]').forEach(el=>el.onclick=()=>root.querySelector(el.dataset.recordAnchor)?.scrollIntoView({behavior:'smooth',block:'start'}));
 if(busy){root.querySelectorAll('button,input,select,textarea').forEach(x=>x.disabled=true);root.querySelector('[data-body-editor]')?.setAttribute('contenteditable','false');}
 bindBodyEditor(root,()=>{if(!busy){collect();dirty=true;}});
 root.querySelector('[data-letter-data]')?.addEventListener('toggle',ev=>{if(ev.target.isConnected)writing=!ev.target.open;});
 root.querySelectorAll('[data-letter-section]').forEach(button=>button.addEventListener('click',()=>{
  const section=button.dataset.letterSection,data=root.querySelector('[data-letter-data]'),annex=root.querySelector('[data-letter-annex]');
  if(data)data.open=section==='data';writing=section!=='data';
  const target=section==='write'?root.querySelector('[data-body-editor]'):section==='data'?root.querySelector('[name=subject]'):annex?.querySelector('input');
  target?.focus({preventScroll:true});(section==='write'?root.querySelector('.records-writing'):section==='data'?data:annex)?.scrollIntoView({block:'start',behavior:'smooth'});
 }));
 root.querySelector('[name=subject]')?.addEventListener('input',ev=>{const title=root.querySelector('[data-paper-subject]');if(title)title.textContent=ev.target.value||t('Asunto por completar','Subject to complete');});
 root.querySelectorAll('[data-records]').forEach(el=>el.onclick=()=>act(el.dataset.records,el.dataset.id));
 root.querySelector('#records-search')?.addEventListener('submit',ev=>{ev.preventDefault();const f=Object.fromEntries(new FormData(ev.target));q=f.q;status=f.status||'';filters=Object.fromEntries(['date_from','date_to','person_id','signer_id','deadline'].map(k=>[k,f[k]||'']));if(filters.date_from&&filters.date_to&&filters.date_from>filters.date_to){showErrors(ev.target,['date_to']);return;}offset=0;run(refresh);});
 root.querySelectorAll('#party-editor,#records-catalog,#records-member,#records-role').forEach(f=>f.addEventListener('input',()=>{dirty=true;}));
 const form=root.querySelector('#record-editor');if(form){form.oninput=ev=>{if(busy||ev.target.type==='file')return;collect();dirty=true;const hint=form.querySelector('.records-save-state');if(hint)hint.textContent=t('Cambios sin guardar','Unsaved changes');};form.onchange=ev=>{if(busy)return;collect();dirty=true;if(ev.target.name==='signer_id')choosingSigner=false;if(['party_','contact_','kind_'].some(prefix=>(ev.target.name||'').startsWith(prefix))||['no_external_number','signer_id'].includes(ev.target.name))draw();};form.onsubmit=ev=>{ev.preventDefault();if(draft.direction==='outgoing'){saveOutgoing();return;}collect();const errors=validateDocument(draft);if(errors.length){showErrors(form,errors);return;}if(draft.direction==='incoming'&&!intakeFile&&!draft.files?.some(f=>f.kind==='incoming')){showErrors(form,['intake_file']);return;}run(async()=>{const id=await api.rpc('save',draft.id||null,draft.version||null,draft);draft.id=id;doc=await api.rpc('read',id);draft.version=doc.version;if(draft.direction==='incoming'){if(intakeFile&&!intakeUploaded){notice=t('Cargando PDF…','Uploading PDF…');draw();await api.upload(doc,intakeFile,'incoming');intakeUploaded=true;doc=await api.rpc('read',id);draft.version=doc.version;}while(pendingAttachments.length){const file=pendingAttachments[0];if(!doc.files.some(f=>f.kind==='attachment'&&f.filename===file.name&&f.size===file.size)){await api.upload(doc,file,'attachment');doc=await api.rpc('read',id);draft.version=doc.version;}pendingAttachments.shift();draft.files=doc.files;}await api.rpc('register',doc.id,doc.version);doc=await api.rpc('read',id);}dirty=false;draft=null;clearIntake();mode='detail';notice=t('Registro completado.','Registration completed.');});};}
 root.querySelector('[name=annex_files]')?.addEventListener('change',async ev=>{
  ev.stopPropagation();const files=[...ev.target.files];if(!files.length)return;collect();
  await run(async()=>{const names=new Set([...(draft.files||[]).filter(f=>f.kind==='attachment').map(f=>f.filename),...pendingAttachments.map(f=>f.name)]);
   for(const file of files){if(names.has(file.name))throw Error('DUPLICATE_ATTACHMENT');names.add(file.name);await inspectRecordFile(file,'attachment');}
   pendingAttachments.push(...files);dirty=true;
  });
 });
 if(form?.querySelector('[name=no_external_number]')?.checked)form.querySelector('[name=external_number]').disabled=true;
 root.querySelector('[name=intake_file]')?.addEventListener('change',async ev=>{ev.stopPropagation();const file=ev.target.files[0];if(!file)return;collect();await run(async()=>{const meta=await inspectRecordFile(file,'incoming');clearIntake();intakeFile=file;intakePages=meta.pages;intakePreview=URL.createObjectURL(file);dirty=true;});});
 root.querySelector('#party-editor')?.addEventListener('submit',saveParty);
 root.querySelector('[name=kind]')?.addEventListener('change',()=>{if(mode==='party'){editing={...editing,...Object.fromEntries(new FormData(root.querySelector('#party-editor')))};draw();}});
 root.querySelector('#records-catalog')?.addEventListener('submit',saveCatalog);
 root.querySelector('#records-member')?.addEventListener('submit',saveMember);
 root.querySelector('[name=member_site_filter]')?.addEventListener('change',ev=>{memberSiteFilter=ev.target.value;root.querySelectorAll('[data-member-site]').forEach(row=>row.hidden=!!memberSiteFilter&&row.dataset.memberSite!==memberSiteFilter);});
 root.querySelector('#records-role')?.addEventListener('submit',saveRole);
 root.querySelector('[name=user_id]')?.addEventListener('change',ev=>{editing=adminData.members.find(m=>m.user_id===ev.target.value)||{user_id:ev.target.value,roles:[]};draw();});
 root.querySelector('#records-member')?.addEventListener('input',()=>{const f=new FormData(root.querySelector('#records-member'));root.querySelector('.records-code').textContent=code(boot.units.find(u=>u.id===f.get('unit_id'))?.code,boot.sites.find(s=>s.id===f.get('site_id'))?.code,f.get('initials'));});
 root.querySelectorAll('[data-upload]').forEach(el=>el.onchange=()=>{if(!el.files[0])return;const file=el.files[0],reason=root.querySelector('[name=replacement_reason]')?.value||'';run(async()=>{await api.upload(doc,file,el.dataset.upload,{reason});doc=await api.rpc('read',doc.id);notice=t('Archivo incorporado al oficio.','File added to the letter.');});});
 root.querySelector('#record-operation')?.addEventListener('submit',operation);
 decorateActions(root);
 }
 function listView(){const incoming=direction==='incoming',drafts=!incoming&&(view==='drafts'||status==='draft');return `<section class="panel"><h2>${viewTitle(direction,view,lang)}</h2><form id="records-search" class="records-toolbar">${input('q',t(incoming?'Buscar número GLF, número de origen, asunto o remitente':'Buscar número GLF, asunto o destinatario',incoming?'Search GLF number, source reference, subject or sender':'Search GLF number, subject or recipient'),q,'maxlength="200"')}<button class="primary">${t('Buscar','Search')}</button>${b('clear',t('Limpiar filtros','Clear filters'))}<details class="records-wide records-filter-details" ${status||Object.values(filters).some(Boolean)?'open':''}><summary>${t('Más filtros','More filters')}</summary><div class="form-grid">${select('status',t('Estado','Status'),opt('',t('Todos','All'),status)+directionStatuses[direction].map(s=>opt(s,recordStatus(s,direction,lang),status)).join(''))}${input('date_from',t(incoming?'Recepción desde':'Fecha del oficio desde',incoming?'Received from':'Letter date from'),filters.date_from,'type="date"')}${input('date_to',t('Hasta','To'),filters.date_to,'type="date"')}${select('person_id',t(incoming?'Responsable':'Autor',incoming?'Owner':'Author'),opt('',t('Todos','All'),filters.person_id)+filterPeople.map(p=>opt(p.id,p.name,filters.person_id)).join(''))}${incoming?select('deadline',t('Plazo de atención','Deadline'),opt('',t('Todos','All'),filters.deadline)+opt('overdue',t('Vencido','Overdue'),filters.deadline)+opt('pending',t('En plazo','Within deadline'),filters.deadline)):select('signer_id',t('Firmante','Signer'),opt('',t('Todos','All'),filters.signer_id)+filterPeople.map(p=>opt(p.id,p.name,filters.signer_id)).join(''))}</div></details><p class="error records-error" role="alert"></p></form></section><section class="panel"><p class="records-result-count" role="status">${total} ${t('resultados','results')} · ${t('Página','Page')} ${Math.floor(offset/50)+1} / ${Math.max(1,Math.ceil(total/50))}</p><div class="table-wrap"><table><thead><tr><th>${t('Número GLF','GLF number')}</th><th>${t('Asunto','Subject')}</th><th>${t(incoming?'Remitente':'Destinatario',incoming?'Sender':'Recipient')}</th><th>${t('Estado','Status')}</th>${drafts?'<th>'+t('Autor','Author')+'</th>':''}<th>${t(incoming?'Recepción':drafts?'Última modificación':'Fecha del oficio',incoming?'Received':drafts?'Last updated':'Letter date')}</th>${incoming?'<th>'+t('Responsable / plazo','Owner / deadline')+'</th>':''}<th></th></tr></thead><tbody>${rows.map(d=>`<tr><td><strong>${esc(number(d))}</strong>${incoming?'<small>'+t('Origen: ','Source: ')+esc(d.external_number||t('Sin número','No number'))+'</small>':''}</td><td>${esc(d.subject)}${d.classification==='restricted'?'<small>'+t('Restringido','Restricted')+'</small>':''}</td><td>${esc(d.correspondent||'—')}</td><td><span class="badge ${['sent','closed'].includes(d.status)?'green':'gray'}">${esc(recordStatus(d.status,d.direction,lang))}</span></td>${drafts?'<td>'+esc(d.author_name||'—')+'</td>':''}<td>${esc(incoming?fmt(d.received_at):drafts?fmt(d.updated_at):d.document_date)}</td>${incoming?'<td>'+esc(d.assigned_name||'—')+'<small>'+esc(d.due_date||'—')+'</small></td>':''}<td>${b(drafts&&d.author_id===profile.id&&can('create')?'resume':'open',drafts&&d.author_id===profile.id&&can('create')?t('Continuar edición','Continue editing'):t('Abrir','Open'),false,`data-id="${d.id}"`)}</td></tr>`).join('')}</tbody></table>${rows.length?'':'<p class="records-empty">'+t('No hay oficios que coincidan con la consulta.','No matching letters.')+'</p>'}</div><div class="records-actions">${b('prev',t('Anterior','Previous'),false,offset?'':'disabled')}${b('next',t('Siguiente','Next'),false,offset+rows.length<total?'':'disabled')}</div></section>`;}

 function contactsView(){return `<section class="panel"><form id="records-search" class="records-toolbar">${input('q',t('Buscar institución o contacto','Search institution or contact'),q,'maxlength="200"')}<button class="primary">${t('Buscar','Search')}</button>${b('party',t('Registrar institución o persona','Register institution or person'),false,can('contacts')?'':'disabled')}</form><p class="records-help">${t('Los proveedores existentes se vinculan desde su ficha; no se duplican sus datos comerciales.','Existing suppliers are linked; their commercial data is not duplicated.')}</p>${parties.map(p=>`<div class="records-file"><span><strong>${esc(p.name)}</strong><br>${esc(p.address)}<br>${esc(p.email||p.contacts?.[0]?.email||'')}</span>${b('contact-edit',t('Agregar contacto','Add contact'),false,`data-id="${p.id}" ${can('contacts')?'':'disabled'}`)}</div>`).join('')}<div class="records-actions">${b('prev',t('Anterior','Previous'),false,offset?'':'disabled')}${b('next',t('Siguiente','Next'),false,parties.length===50?'':'disabled')}</div></section>`;}
 function partyForm(){const p=editing||{};return `<form id="party-editor" class="panel"><h2>${t(p.id?'Agregar contacto':'Registrar contraparte',p.id?'Add contact':'Register correspondent')}</h2><div class="form-grid">${!p.id?select('supplier_id',t('Vincular proveedor existente (opcional)','Link existing supplier (optional)'),pick()+suppliers.map(s=>opt(s.id,`${s.legal_name} · ${s.id_number}`,p.supplier_id)).join('')):''}${select('kind',t('Tipo de persona','Person type'),opt('institution',t('Institución / persona jurídica','Institution / legal entity'),p.kind||'institution')+opt('natural',t('Persona natural','Individual'),p.kind))}${input('name',p.kind==='natural'?t('Nombres y apellidos','Full name'):t('Institución o razón social','Institution or legal name'),p.name,'maxlength="250"')}${input('address',t('Dirección','Address'),p.address,'maxlength="1000"')}${input('contact_name',p.kind==='natural'?t('Nombre del contacto (opcional)','Contact name (optional)'):t('Representante legal o máxima autoridad','Legal representative or highest authority'),'','maxlength="250"')}${input('job_title',t('Cargo','Job title'),'','maxlength="160"')}${input('email',t('Correo electrónico','Email'),'','type="email" maxlength="250"')}${input('phone',t('Teléfono','Phone'),'','type="tel" maxlength="40"')}</div><div class="records-actions"><button class="primary">${t('Guardar','Save')}</button>${b('party-cancel',t('Cancelar','Cancel'))}</div></form>`;}
 async function saveParty(ev){ev.preventDefault();const f=Object.fromEntries(new FormData(ev.target));if(!f.supplier_id&&!editing?.supplier_id&&f.name.trim().length<2){showErrors(ev.target,['name']);return;}run(async()=>{const p=await api.rpc('party',editing?.id||null,editing?.version||null,{supplier_id:f.supplier_id||editing?.supplier_id||null,kind:f.kind,name:f.name,address:f.address,contact:[f.contact_name,f.job_title,f.email,f.phone].some(v=>v?.trim())?{name:f.contact_name,job_title:f.job_title,email:f.email,phone:f.phone,is_representative:f.kind==='institution'}:undefined});parties=await api.rpc('parties');if(!parties.some(x=>x.id===p.id))parties.unshift(p);editing=null;if(partyBack){const recipient={party_id:p.id,contact_id:p.contacts?.filter(c=>[c.name,c.job_title,c.email,c.phone].some(Boolean)).at(-1)?.id||null,kind:draft.direction==='incoming'?'from':'to'};const empty=draft.recipients.findIndex(r=>!r.party_id);if(empty>=0)draft.recipients[empty]=recipient;else draft.recipients.push(recipient);mode='edit';dirty=true;}else{mode='contacts';q='';dirty=false;}notice=t('Registro guardado.','Record saved.');});}
 function editor(){const d=draft;return `<form id="record-editor" class="panel records-editor" novalidate><h2>${t(d.direction==='incoming'?'Registrar oficio recibido':'Redactar oficio',d.direction==='incoming'?'Register incoming letter':'Draft letter')}</h2>${d.direction==='outgoing'?'<details class="records-editor-help"><summary>ⓘ '+t('Ayuda para redactar','Writing help')+'</summary><p class="records-help">'+t('Para guardar un borrador basta con indicar el asunto. Complete destinatario, contenido y firmante antes de remitirlo para firma.','Only a subject is needed to save a draft. Complete the recipient, content and signer before submitting for signature.')+'</p></details>':''}<div class="records-actions records-editor-actions"><button class="primary">${t(d.direction==='incoming'?'Registrar recepción':'Guardar borrador',d.direction==='incoming'?'Register reception':'Save draft')}</button>${d.direction==='outgoing'?b('preview',t('Vista previa','Preview')):''}${b('cancel-edit',t('Volver','Back'))}<span class="records-save-state">${dirty?t('Cambios sin guardar','Unsaved changes'):''}</span></div><p class="error records-error" id="record-errors" role="alert"></p>${d.direction==='outgoing'?'<nav class="records-writing-nav" aria-label="'+t('Secciones del oficio','Letter sections')+'"><button type="button" class="secondary" data-letter-section="data">'+t('Datos del oficio','Letter details')+'</button><button type="button" class="secondary" data-letter-section="write">'+t('Redactar','Write')+'</button><button type="button" class="secondary" data-letter-section="annex">'+t('Anexos','Attachments')+'</button></nav><details class="records-letter-data" data-letter-data '+(!writing?'open':'')+'><summary>'+t('Asunto, destinatarios y firmante','Subject, recipients and signatory')+'</summary>':''}<div class="form-grid"><div class="records-wide">${input('subject',t('Asunto *','Subject *'),d.subject,'required minlength="3" maxlength="300"')}</div>${d.direction==='incoming'?input('document_date',t('Fecha del oficio de origen *','Source letter date *'),d.document_date,`type="date" required max="${day()}"`):'<div class="records-auto"><strong>'+t('Fecha del oficio · automática','Letter date · automatic')+'</strong><span>'+esc(fmt(boot.server_time||new Date().toISOString()))+' (Galápagos)</span><small>'+t('Se actualiza al guardar y se fija al aprobar el oficio.','Updated on save and fixed when the letter is approved.')+'</small></div>'}${d.direction==='outgoing'?'':input('external_number',t('Número del oficio de origen','Source letter number'),d.external_number,'maxlength="160"')+`<label class="records-inline"><input type="checkbox" name="no_external_number" ${d.no_external_number?'checked':''}>${t('Sin número de origen','No source number')}</label>`}${select('classification',t('Visibilidad','Visibility'),opt('ordinary',t('Ordinario · consulta interna','Ordinary · internal access'),d.classification)+opt('restricted',t('Restringido · personas autorizadas','Restricted · authorized people'),d.classification))}${d.direction==='outgoing'?signerField(d):input('received_at',t('Fecha y hora de recepción · Galápagos *','Received date and time · Galápagos *'),d.received_at_local,`type="datetime-local" required max="${localDateTime()}"`)}${d.direction==='incoming'?select('channel',t('Canal de recepción','Received via'),[['email','Correo electrónico','Email'],['physical','Físico','Physical'],['portal','Portal','Portal'],['other','Otro','Other']].map(([v,es,en])=>opt(v,t(es,en),d.channel)).join(''))+input('physical_location',t('Ubicación del original físico (opcional)','Physical original location (optional)'),d.physical_location,'maxlength="1000"'):''}<div class="records-wide"><h3>${t(d.direction==='incoming'?'Remitente':'Destinatarios',d.direction==='incoming'?'Sender':'Recipients')}</h3><div class="records-participant-actions">${b('choose-party',t(d.direction==='incoming'?'Buscar remitente':'Buscar destinatario',d.direction==='incoming'?'Search sender':'Search recipient'))}</div><div class="records-recipients">${d.recipients.map((r,i)=>`<div class="records-recipient">${select('party_'+i,t('Institución o persona','Institution or person'),pick()+parties.map(p=>opt(p.id,p.name,r.party_id)).join(''))}${select('contact_'+i,t('Contacto','Contact'),opt('',t('Contacto principal','Main contact'),r.contact_id)+ (parties.find(p=>p.id===r.party_id)?.contacts||[]).filter(c=>[c.name,c.job_title,c.email,c.phone].some(Boolean)).map(c=>opt(c.id,[c.name,c.job_title,c.email].filter(Boolean).join(' · '),r.contact_id)).join(''))}${d.direction==='outgoing'?select('kind_'+i,t('Destinatario','Recipient'),opt('to',t('Para','To'),r.kind)+opt('cc',t('Copia','Cc'),r.kind)):''}${b('remove-recipient',t('Quitar','Remove'),false,`data-id="${i}"`)}</div>`).join('')}</div><div class="records-actions">${b('add-recipient',t(d.direction==='incoming'?'Agregar remitente':'Agregar destinatario',d.direction==='incoming'?'Add sender':'Add recipient'))}${b('party-from-editor',t('Registrar o vincular contraparte','Register or link correspondent'),false,can('contacts')?'':'disabled')}</div></div>${d.direction==='outgoing'?'</div><button type="button" class="primary records-start-writing" data-letter-section="write">'+t('Redactar contenido','Write content')+'</button></details><div class="form-grid">':''}<section class="records-wide records-writing"><h3 id="records-body-label">${t(d.direction==='incoming'?'Resumen / observaciones':'Contenido del oficio',d.direction==='incoming'?'Summary / notes':'Letter content')}</h3>${d.direction==='outgoing'?bodyEditor(d):`<textarea class="records-body" name="body" aria-labelledby="records-body-label" maxlength="60000">${esc(d.body)}</textarea>`}<small class="records-help">${d.direction==='incoming'?t('Registre observaciones sobre el documento recibido; el archivo original se conserva intacto.','Add notes about the incoming document; the original file is preserved.'):t('Puede incorporar un Word de origen después de guardar el borrador.','You can attach a source Word document after saving the draft.')}</small></section>${d.direction==='incoming'?intakeFields()+annexEditor(d):annexEditor(d)}</div></form>`;}
 function bodyEditor(d){
  const svg=path=>'<svg viewBox="0 0 24 24" width="22" height="22" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">'+path+'</svg>';
  const controls=[['bold','',t('Negrita','Bold'),'<path d="M6 4h7a4 4 0 0 1 0 8H6zm0 8h8a4 4 0 0 1 0 8H6z"/>'],['justifyLeft','left',t('Alinear a la izquierda','Align left'),'<path d="M4 5h16M4 10h10M4 15h16M4 20h10"/>'],['justifyCenter','center',t('Centrar','Center'),'<path d="M4 5h16M7 10h10M4 15h16M7 20h10"/>'],['justifyFull','justify',t('Justificar','Justify'),'<path d="M4 5h16M4 10h16M4 15h16M4 20h16"/>']];
  const image=typeof __RECORDS_LOGO__==='undefined'?logo:__RECORDS_LOGO__;
  const signer=boot.signers.find(s=>s.id===d.signer_id);
  const recipients=d.recipients.filter(r=>r.kind==='to'&&r.party_id).map(r=>{const p=parties.find(p=>p.id===r.party_id);const c=p?.contacts?.find(c=>c.id===r.contact_id)||p?.contacts?.[0];return [c?.name,c?.job_title,p?.name].filter(Boolean).map(esc).join('<br>');}).join('<br><br>');
  const paperDate=new Intl.DateTimeFormat(lang==='es'?'es-EC':'en-GB',{dateStyle:'long',timeZone:'Pacific/Galapagos'}).format(new Date(boot.server_time||Date.now()));
  return '<div class="records-format-toolbar" role="group" aria-label="'+t('Formato del contenido','Content formatting')+'">'+controls.map(([command,align,label,path])=>'<button type="button" class="secondary" data-body-command="'+command+'" data-align="'+align+'" aria-label="'+label+'" title="'+label+'" aria-pressed="false">'+svg(path)+'</button>').join('')+'<span class="records-font-note">Times New Roman · 11 pt</span></div><div class="records-writing-desk"><article class="records-paper"><header class="records-paper-heading"><span>Galápagos Life Fund</span>'+(image?'<img src="'+image+'" alt="GLF">':'')+'</header><p class="records-paper-date">'+esc(paperDate)+'</p><p class="records-paper-subject"><strong>'+t('Asunto: ','Subject: ')+'</strong><span data-paper-subject>'+esc(d.subject||t('Asunto por completar','Subject to complete'))+'</span></p>'+(recipients?'<p class="records-paper-recipient">'+recipients+'</p>':'')+'<p class="records-paper-greeting">'+t('De mi consideración:','Dear Sir or Madam:')+'</p><div class="records-body records-rich" data-body-editor contenteditable="true" spellcheck="true" lang="'+lang+'" role="textbox" aria-multiline="true" aria-labelledby="records-body-label" aria-describedby="records-writing-help">'+bodyHtml(d.body,d.body_format)+'</div><div class="records-paper-signatory"><p>'+t('Atentamente,','Sincerely,')+'</p><p><strong>'+esc(signer?.name||t('Firmante por asignar','Signatory to assign'))+'</strong><br>'+esc(signer?.job_title||'')+'</p></div></article></div><input type="hidden" name="body" value="'+esc(d.body||'')+'"><small id="records-writing-help" class="records-help">'+t('Escriba el cuerpo del oficio. Seleccione texto para negrita o aplique la alineación al párrafo. El PDF organiza las páginas y añade destinatarios y firma.','Write the letter body. Select text for bold or apply alignment to a paragraph. The PDF arranges pages and adds recipients and the signatory.')+'</small>';
 }
 function collect(){const form=root.querySelector('#record-editor');if(!form||!draft)return;const f=new FormData(form);for(const name of ['subject','document_date','place','classification','signer_id','external_number','channel','body','physical_location'])if(f.has(name))draft[name]=f.get(name);const rich=form.querySelector('[data-body-editor]');if(rich)Object.assign(draft,readBodyEditor(rich));draft.no_external_number=f.has('no_external_number');if(draft.no_external_number)draft.external_number='';if(f.has('received_at')){draft.received_at_local=f.get('received_at');try{draft.received_at=dateTimeToISO(draft.received_at_local);}catch{draft.received_at='';}}draft.recipients=draft.recipients.map((r,i)=>({party_id:f.get('party_'+i)||'',contact_id:f.get('contact_'+i)||null,kind:draft.direction==='incoming'?'from':f.get('kind_'+i)||'to'}));}
 function showErrors(form,names){form.querySelectorAll('[aria-invalid]').forEach(x=>x.removeAttribute('aria-invalid'));for(const name of names){const el=form.querySelector(`[name="${name==='party_id'?'party_0':name}"]`);if(el){el.setAttribute('aria-invalid','true');const panel=el.closest('details');if(panel)panel.open=true;}if(name==='body')form.querySelector('[data-body-editor]')?.setAttribute('aria-invalid','true');}const p=form.querySelector('.records-error');if(p)p.textContent=t('Revise los campos resaltados antes de guardar.','Review the highlighted fields before saving.');else{error=t('Revise los datos obligatorios.','Review required fields.');}form.querySelector('[data-body-editor][aria-invalid],:not([type=hidden])[aria-invalid]')?.focus();}
 function detail(){const d=doc,isAuthor=d.author_id===profile.id,isSigner=d.signer_id===profile.id;return `<section class="panel"><div class="records-summary"><h2>${esc(number(d))} · ${esc(d.subject)}</h2>${statusBadge(d.status)}</div><p>${esc(d.origin_code)} · ${esc(d.author_name)} · ${esc(d.document_date)}${d.classification==='restricted'?' · '+t('Restringido','Restricted'):''}</p><div class="records-actions">${b('documents',t('Volver al listado','Back to list'))}${d.status==='draft'&&isAuthor?b('edit',t(d.direction==='incoming'?'Completar recepción':'Continuar edición',d.direction==='incoming'?'Complete reception':'Continue editing'))+(d.direction==='outgoing'?b('submit',t('Remitir para firma','Submit for signature'),true):''):''}${d.direction==='incoming'&&!d.internal_number&&d.status!=='draft'&&can('receive')?b('register',t('Asignar número de ingreso GLF','Assign GLF receipt number'),true):''}${d.status==='review'&&isSigner&&can('sign')?b('approve',t('Aprobar y preparar PDF','Approve and prepare PDF'),true)+b('return',t('Devolver con observaciones','Return with comments')):''}${d.direction==='outgoing'?b('preview',t('Vista previa','Preview'))+b('pdf',t('Descargar PDF','Download PDF')):''}${d.direction==='incoming'&&['received','assigned'].includes(d.status)&&can('create')?b('reply',replyDraft(d)?t('Continuar respuesta','Continue reply'):t('Responder','Reply')):''}${['sent','received','assigned'].includes(d.status)&&can('archive')?b('close',t('Cerrar y archivar','Close and archive')):''}</div><nav class="records-section-links" aria-label="${t('Secciones del oficio','Letter sections')}"><button type="button" class="secondary" data-record-anchor=".records-content-panel">${t('Documento','Document')}</button><button type="button" class="secondary" data-record-anchor=".records-documents-panel">${t('Anexos','Attachments')}</button><button type="button" class="secondary" data-record-anchor=".records-followup-panel">${t('Seguimiento','Follow-up')}</button></nav></section><div class="records-detail"><section class="panel records-content-panel"><h2>${t(d.direction==='incoming'?'Oficio recibido':'Contenido',d.direction==='incoming'?'Received letter':'Content')}</h2>${d.direction==='incoming'?mainLetterView(d):''}${d.recipients.filter(r=>d.direction!=='outgoing'||r.kind!=='cc').map(r=>`<p><strong>${esc(r.party?.name)}</strong><br>${esc(r.contact?.name||r.party?.representative||'')} ${esc(r.contact?.job_title||'')}</p>`).join('')}${d.direction==='outgoing'?'<div class="records-preview">'+bodyHtml(d.body,d.body_format)+'</div><p><strong>'+esc(d.signer_name||'')+'</strong><br>'+esc(d.job_title||'')+'</p>'+annexList(d):(d.body?'<div class="records-preview">'+esc(d.body)+'</div>':'')}${d.direction==='outgoing'&&d.recipients.some(r=>r.kind==='cc')?'<h3>'+t('Copia:','Cc:')+'</h3>'+d.recipients.filter(r=>r.kind==='cc').map(r=>`<p>${esc(r.contact?.name||r.party?.representative||'')}<br><strong>${esc(r.contact?.job_title||'')}</strong><br>${esc(r.party?.name||'')}</p>`).join(''):''}${d.direction==='incoming'?'<p>'+t('Número de origen: ','Source number: ')+esc(d.external_number||t('Sin número','No number'))+'</p><p>'+t('Recibido: ','Received: ')+fmt(d.received_at)+'</p>'+(d.physical_location?'<p>'+t('Original físico: ','Physical original: ')+esc(d.physical_location)+'</p>':''):''}${relatedView()}${d.direction==='incoming'?'':operationView()}</section><section class="panel records-documents-panel"><h2>${d.direction==='incoming'?t('Anexos y documentos de respaldo','Attachments and supporting documents'):t('Documentos y anexos','Documents and attachments')}</h2>${d.files.filter(f=>d.direction!=='incoming'||f.kind!=='incoming').map(f=>`<div class="records-file"><span>${esc(f.filename)}<small> · ${Math.ceil(f.size/1024)} KB</small></span>${b('download',t('Descargar','Download'),false,`data-id="${f.id}"`)}${f.mime==='application/vnd.openxmlformats-officedocument.wordprocessingml.document'&&d.status==='draft'&&isAuthor?b('word',t('Usar texto de Word','Use Word text'),false,`data-id="${f.id}"`):''}</div>`).join('')||`<p>${d.direction==='incoming'?t('Sin anexos ni documentos adicionales.','No attachments or additional documents.'):t('Sin archivos.','No files.')}</p>`}${d.direction==='outgoing'&&d.status==='draft'&&isAuthor?upload('source',t('Adjuntar Word de origen o PDF','Attach source Word or PDF'),'.docx,.pdf')+upload('attachment',t('Agregar anexo PDF','Add PDF attachment')):''}${d.direction==='incoming'&&can('receive')&&['received','assigned'].includes(d.status)?(d.files.some(f=>f.kind==='incoming')?input('replacement_reason',t('Motivo de la nueva versión *','Reason for new version *'),'','minlength="5" maxlength="3000"'):'')+upload('incoming',t(d.files.some(f=>f.kind==='incoming')?'Incorporar nueva versión PDF':'Incorporar oficio recibido PDF',d.files.some(f=>f.kind==='incoming')?'Add new PDF version':'Upload incoming letter PDF'))+upload('attachment',t('Agregar anexo PDF','Add PDF attachment')):''}${d.status==='prepared'&&isSigner&&can('sign')?upload('signed',t('Subir PDF firmado electrónicamente','Upload electronically signed PDF')):''}${d.status==='prepared'&&isSigner&&d.files.some(f=>f.kind==='signed')?b('verify',t('Registrar verificación de firma','Record signature verification'),true):''}${d.status==='signed'&&can('dispatch')?`<p class="records-help">${t('Prepare el correo para consultar la conexión institucional. Si no está disponible, puede enviar manualmente el PDF firmado y registrar su constancia.','Prepare the email to check the institutional connection. If unavailable, send the signed PDF manually and record its evidence.')}</p>${b('email',t('Preparar correo','Prepare email'),true)}${upload('proof',t('Subir constancia de envío PDF','Upload delivery evidence PDF'))}${b('manual_sent',t('Registrar envío realizado','Record completed delivery'))}`:''}${d.dispatches?.some(s=>['sending','uncertain'].includes(s.status))?`<p class="error" role="status">${t('El resultado del envío requiere comprobación. No repita el envío; verifique el buzón institucional antes de resolverlo.','Delivery requires verification. Do not resend; check the institutional mailbox before resolving it.')}</p>`:''}</section><section class="panel records-history-panel records-followup-panel">${followupView(d)}</section></div>`;}
 const upload=(kind,text,accept='.pdf')=>`<label class="records-help">${esc(text)}<input type="file" data-upload="${kind}" accept="${accept}"><small>${t('Máximo 20 MB por archivo.','Maximum 20 MB per file.')}</small></label>`;
 let op=null,mail={configured:false};
 function operationView(){if(!op)return '';const d=doc;return `<form id="record-operation" class="records-note"><h3>${esc(op.title)}</h3>${['assign','directive'].includes(op.action)?select('assigned_to',t('Responsable','Owner'),pick()+(adminData?.users||boot.signers).map(u=>opt(u.id,u.name,d.assigned_to)).join(''))+input('due_date',t('Fecha límite (opcional)','Due date (optional)'),d.due_date||'','type="date"')+`<label><input type="checkbox" name="requires_response" ${d.requires_response?'checked':''}>${t('Requiere respuesta','Response required')}</label>`:''}${op.action==='verify'?`<p>${t('Verifique el PDF con su herramienta de firma. Compruebe firmante, integridad y contenido aprobado. Esta acción registra su revisión; no es una validación criptográfica automática.','Verify the PDF with your signature tool. Check the signer, integrity and approved content. This records your review; it is not automatic cryptographic validation.')}</p>${select('file_id',t('PDF revisado','Reviewed PDF'),d.files.filter(f=>f.kind==='signed').map(f=>opt(f.id,f.filename,'')).join(''))}`:''}${['email','manual_sent'].includes(op.action)?input('email',t('Destinatario','Recipient'),invitationMail(d,lang).to,'type="email" multiple required')+input('cc',t('Copia (opcional)','Cc (optional)'),invitationMail(d,lang).cc,'type="email" multiple')+ (op.action==='manual_sent'?select('proof_file_id',t('Constancia','Evidence'),pick()+d.files.filter(f=>f.kind==='proof').map(f=>opt(f.id,f.filename,'')).join('')):''):''}${op.action==='email'&&mail.configured?`<p>${t('Se enviará desde','Will be sent from')} ${esc(mail.from)}. ${t('Se adjuntarán el PDF firmado y los anexos del oficio.','The signed PDF and letter attachments will be included.')}</p>`:''}${op.action==='email'?input('subject',t('Asunto','Subject'),invitationMail(d,lang).subject)+`<label>${t('Mensaje','Message')}<textarea name="message" rows="7">${esc(invitationMail(d,lang).message)}</textarea></label>`:`<label>${(op.action==='directive'?t('Disposición / instrucción *','Instruction *'):op.action==='attention'?t('Atención realizada *','Action taken *'):op.action==='assign'?t('Motivo / instrucción de asignación *','Assignment instruction *'):t('Motivo / evidencia','Reason / evidence'))}<textarea name="reason" required minlength="${['verify','manual_sent'].includes(op.action)?10:5}" maxlength="3000"></textarea></label>`}${op.action==='attention'?select('evidence_file_id',t('Documento de respaldo (opcional)','Supporting file (optional)'),opt('',t('Sin documento','No file'),'')+d.files.map(f=>opt(f.id,f.filename,'')).join('')):''}<div class="records-actions"><button class="primary">${op.action==='email'?(mail.configured?t('Enviar oficio','Send letter'):t('Copiar mensaje','Copy message')):t('Confirmar','Confirm')}</button>${b('cancel-operation',t('Cancelar','Cancel'))}</div></form>`;}
 async function operation(ev){ev.preventDefault();const f=Object.fromEntries(new FormData(ev.target));if(op.action==='email'&&mail.configured){await run(async()=>{await api.send(doc,f);op=null;doc=await api.rpc('read',doc.id);notice=t('Gmail aceptó el envío. Esto no confirma lectura ni entrega al destinatario.','Gmail accepted the message. This does not confirm delivery or reading.');});return;}if(op.action==='email'){await navigator.clipboard.writeText(`${f.email}\n${f.cc?"Cc: "+f.cc+"\n":""}${f.subject}\n\n${f.message}`);notice=t('Mensaje copiado. No se ha enviado un correo. Adjunte el PDF firmado al enviarlo.','Message copied. No email was sent. Attach the signed PDF when sending.');op=null;draw();return;}run(async()=>{await api.rpc(op.action,doc.id,doc.version,{...f,requires_response:!!f.requires_response});op=null;doc=await api.rpc('read',doc.id);notice=t('Acción registrada.','Action recorded.');});}
 function eventLabel(a){if(["register","directive","attention","reply_created"].includes(a))return followupLabels[a][lang==='es'?0:1];return ({dispatch_prepared:t('Correo preparado','Email prepared'),dispatch_sent:t('Envío aceptado por Gmail','Email accepted by Gmail'),dispatch_failed:t('Envío rechazado','Email rejected'),dispatch_uncertain:t('Envío por verificar','Delivery to verify'),saved:t('Oficio guardado','Letter saved'),submit:t('Remitido para firma','Submitted for signature'),approve:t('Aprobado y numerado','Approved and numbered'),return:t('Devuelto con observaciones','Returned with comments'),confirm_upload:t('Archivo incorporado','File uploaded'),verify:t('Verificación de firma registrada','Signature review recorded'),manual_sent:t('Envío manual registrado','Manual dispatch recorded'),assign:t('Responsable asignado','Owner assigned'),close:t('Cerrado','Closed')})[a]||a;}
 function adminView(){if(!boot.admin)return `<section class="panel">${t('Requiere permiso de administración.','Administrator permission required.')}</section>`;if(!adminData)return '';const members=adminData.members||[],selected=editing||{};return `<div class="records-tabs">${[['units','Direcciones','Units'],['sites','Sedes','Sites'],['roles','Perfiles','Roles'],['members','Asignaciones','Assignments']].map(([key,es,en])=>b('admin-'+key,t(es,en),adminTab===key)).join('')}</div><section class="panel">${['units','sites'].includes(adminTab)?`<div class="table-wrap"><table><thead><tr><th>${t('Nombre','Name')}</th><th>${t('Sigla','Code')}</th><th>${t('Estado','Status')}</th><th></th></tr></thead><tbody>${boot[adminTab].map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.code)}</td><td>${t(x.active?'Activo':'Inactivo',x.active?'Active':'Inactive')}</td><td>${b('catalog-edit',t('Editar','Edit'),false,`data-id="${x.id}"`)}</td></tr>`).join('')}</tbody></table></div><form id="records-catalog"><h3>${t(selected.id?'Editar registro':'Agregar registro',selected.id?'Edit record':'Add record')}</h3><div class="form-grid">${input('name',t('Nombre *','Name *'),selected.name,'required minlength="2" maxlength="120"')}${input('code',t('Sigla *','Code *'),selected.code,`required pattern="[A-Z]{2,${adminTab==='sites'?6:10}}" ${selected.id?'readonly':''}`)}${selected.id?select('active',t('Estado','Status'),opt('true',t('Activo','Active'),String(selected.active))+opt('false',t('Inactivo','Inactive'),String(selected.active))):''}${input('reason',t('Motivo *','Reason *'),'','required minlength="5" maxlength="1000"')}</div><p class="records-help">${t('La sigla identifica una unidad de forma estable. Para reemplazarla, cree la nueva unidad y reasigne el personal; los oficios emitidos conservan su referencia.','Codes identify units permanently. To replace one, create the successor and reassign staff; issued letters retain their reference.')}</p><div class="records-actions"><button class="primary">${t('Guardar','Save')}</button>${b('admin-clear',t('Nuevo','New'))}</div></form>`:adminTab==='roles'?`<div class="records-actions">${adminData.roles.map(r=>b('role-edit',r.name,false,`data-id="${r.id}"`)).join('')}</div><form id="records-role"><h3>${t('Perfil de correspondencia','Correspondence role')}</h3>${input('name',t('Nombre *','Name *'),selected.name,'required minlength="2" maxlength="100"')}<div class="records-checks">${Object.entries(permissionLabels).map(([key,labels])=>`<label><input type="checkbox" name="permission" value="${key}" ${selected.permissions?.includes(key)?'checked':''}>${esc(labels[lang==='es'?0:1])}</label>`).join('')}</div>${input('reason',t('Motivo *','Reason *'),'','required minlength="5" maxlength="1000"')}<div class="records-actions"><button class="primary">${t('Guardar perfil','Save role')}</button>${b('admin-clear',t('Nuevo','New'))}</div></form>`:`<p class="records-help">${t('Seleccione una cuenta existente. Las altas y accesos a otras aplicaciones se conservan en Usuarios y accesos.','Select an existing account. Account provisioning and other application access remain in Users and access.')}</p><form id="records-member"><div class="form-grid">${select('user_id',t('Usuario *','User *'),pick()+adminData.users.filter(u=>u.active).map(u=>opt(u.id,u.name,selected.user_id)).join(''))}${select('unit_id',t('Dirección o área *','Unit *'),pick()+boot.units.filter(u=>u.active).map(u=>opt(u.id,u.name,selected.unit_id)).join(''))}${select('site_id',t('Sede de trabajo *','Work site *'),pick()+boot.sites.filter(s=>s.active).map(s=>opt(s.id,s.name,selected.site_id)).join(''))}${input('job_title',t('Cargo *','Job title *'),selected.job_title,'required minlength="2" maxlength="160"')}${input('initials',t('Iniciales *','Initials *'),selected.initials,'required pattern="[A-Z]{2,8}" maxlength="8"')}${input('reason',t('Motivo *','Reason *'),'','required minlength="5" maxlength="1000"')}</div><output class="records-code">${esc(code(boot.units.find(u=>u.id===selected.unit_id)?.code,boot.sites.find(s=>s.id===selected.site_id)?.code,selected.initials))}</output><div class="records-checks">${adminData.roles.map(r=>`<label><input type="checkbox" name="role" value="${r.id}" ${selected.roles?.includes(r.id)?'checked':''}>${esc(r.name)}</label>`).join('')}</div><p class="records-help">${t('Asignar una dirección no concede firma o recepción. Revise los perfiles seleccionados.','Assigning a unit does not grant signing or reception. Review selected roles.')}</p><button class="primary">${t('Guardar asignación','Save assignment')}</button></form><h3>${t('Usuarios por sede','Users by work site')}</h3>${select('member_site_filter',t('Filtrar usuarios por sede','Filter users by work site'),opt('',t('Todas las sedes','All sites'),memberSiteFilter)+boot.sites.map(s=>opt(s.id,s.name,memberSiteFilter)).join(''))}<div class="table-wrap"><table><thead><tr><th>${t('Usuario','User')}</th><th>${t('Dirección o área','Unit')}</th><th>${t('Sede de trabajo','Work site')}</th><th>${t('Cargo','Job title')}</th><th>${t('Siglas de origen','Origin code')}</th></tr></thead><tbody>${members.map(m=>`<tr data-member-site="${esc(m.site_id)}" ${memberSiteFilter&&memberSiteFilter!==m.site_id?'hidden':''}><td>${esc(adminData.users.find(u=>u.id===m.user_id)?.name)}</td><td>${esc(boot.units.find(u=>u.id===m.unit_id)?.name)}</td><td>${esc(boot.sites.find(s=>s.id===m.site_id)?.name)}</td><td>${esc(m.job_title)}</td><td>${esc(code(boot.units.find(u=>u.id===m.unit_id)?.code,boot.sites.find(s=>s.id===m.site_id)?.code,m.initials))}</td></tr>`).join('')}</tbody></table></div>`}</section>`;}
 async function saveCatalog(ev){ev.preventDefault();const f=Object.fromEntries(new FormData(ev.target));run(async()=>{await api.rpc(adminTab==='units'?'unit':'site',editing?.id||null,editing?.version||null,{...f,active:f.active!=='false'});editing=null;dirty=false;await refresh();notice=t('Catálogo actualizado.','Catalog updated.');});}
 async function saveMember(ev){ev.preventDefault();const f=new FormData(ev.target),data={...Object.fromEntries(f),roles:f.getAll('role')};if(!data.user_id||!data.unit_id||!data.site_id){showErrors(ev.target,['user_id','unit_id','site_id']);return;}run(async()=>{await api.rpc('member',null,editing?.version||null,data);editing=null;dirty=false;await refresh();notice=t('Asignación guardada.','Assignment saved.');});}
 async function saveRole(ev){ev.preventDefault();const f=new FormData(ev.target);run(async()=>{await api.rpc('role',editing?.id||null,editing?.version||null,{name:f.get('name'),reason:f.get('reason'),permissions:f.getAll('permission')});editing=null;dirty=false;await refresh();notice=t('Perfil actualizado. Revise sus usuarios asignados.','Role updated. Review its assigned users.');});}
 async function act(action,id){if(busy)return;
 if(action==='choose-party'){collect();await chooseParty();return;}
 if(action==='preview'||action==='view-main'){
  collect();await run(async()=>{if(action==='view-main'){const f=doc.files.find(f=>f.id===id&&f.kind==='incoming');if(!f)throw Error('INVALID_FILE');await showPreview(await api.download(f),f.filename);}else{const {recordsPdf}=await import('./records-pdf.js');const snapshot=draft?snapshotDraft():(doc.revisions?.[0]?.snapshot||doc);const pdf=recordsPdf({...snapshot,attachments:snapshot.attachments||recordAttachments(doc)},{logo,lang,draft:!!draft||!doc.sequence});await showPreview(new Blob([pdf.buffer],{type:'application/pdf'}),pdf.filename);}});return;
 }
 if(['tray','inbox','outbox','drafts','all-outgoing'].includes(action)){
  if(!await leave())return;rememberList();let dir=direction,next='all';
  if(action==='tray')[dir,next]=id.split(':');else dir=action==='inbox'?'incoming':'outgoing';if(action==='drafts')next='drafts';
  restoreList(filterCache[workspaceKey(dir,next)]||{direction:dir,view:next,q:'',status:'',offset:0,filters:{},scroll:0});
  mode='documents';doc=null;draft=null;dirty=false;op=null;notice='';clearIntake();await run(refresh);return;
 }
 if(action==='documents'&&returnView){if(!await leave())return;restoreList(returnView);mode='documents';doc=null;draft=null;dirty=false;op=null;notice='';await run(refresh);return;}
 if(['open','resume','new','incoming','contacts'].includes(action))rememberList();
if(action==='change-signer'){collect();choosingSigner=!choosingSigner;draw();return;}if(action==='remove-pending-annex'){collect();pendingAttachments.splice(Number(id),1);dirty=true;draw();return;}if(action==='retry'){run(refresh);return;}if(action==='cancel-operation'){op=null;draw();return;}if(action.startsWith('admin-')){if(!await leave())return;dirty=false;adminTab=action==='admin-clear'?adminTab:action.slice(6);editing=null;draw();return;}if(action==='catalog-edit'){editing=boot[adminTab].find(x=>x.id===id);draw();return;}if(action==='role-edit'){editing=adminData.roles.find(x=>x.id===id);draw();return;}if(action==='remove-recipient'){collect();draft.recipients.splice(Number(id),1);dirty=true;draw();return;}if(action==='add-recipient'){collect();draft.recipients.push({party_id:'',kind:draft.direction==='incoming'?'from':'to'});dirty=true;draw();return;}
 if(action==='search-parties'){collect();const term=root.querySelector('[name=party_search]')?.value||'';const selected=parties.filter(p=>draft.recipients.some(r=>r.party_id===p.id));await run(async()=>{parties=await api.rpc('parties',null,null,{q:term});for(const p of selected)if(!parties.some(x=>x.id===p.id))parties.push(p);});return;}
 if(action==='contact-edit'){editing=parties.find(p=>p.id===id);partyBack=false;mode='party';draw();return;}
 if(action==='party-from-editor'){collect();partyBack=true;editing=null;mode='party';draw();return;}
 if(action==='party-cancel'){mode=partyBack?'edit':'contacts';editing=null;draw();return;}
 if(['assign','directive','attention','verify','return','close','email','manual_sent'].includes(action)){op={action,title:({directive:t('Registrar disposición','Record instruction'),attention:t('Registrar atención','Record action taken'),assign:t('Asignar o reasignar','Assign or reassign'),verify:t('Verificación de firma','Signature verification'),return:t('Devolver con observaciones','Return with comments'),close:t('Cerrar oficio','Close letter'),email:t('Correo preparado','Prepared email'),manual_sent:t('Registrar envío realizado','Record completed delivery')})[action]};if(['assign','directive'].includes(action))await run(async()=>{adminData={users:await api.rpc('assignees')};});else if(action==='email')await run(async()=>{mail=await api.mailStatus?.()||{configured:false};});else draw();root.querySelector('#record-operation')?.scrollIntoView({block:'center'});return;}
 if(action==='word'){await run(async()=>{const file=doc.files.find(f=>f.id===id);const {extractWord}=await import('./records-word.js');const text=await extractWord(await api.download(file));draft={...structuredClone(doc),body:text,body_format:null,recipients:doc.recipients.map(r=>({party_id:r.party.id,contact_id:r.contact_id,kind:r.kind}))};parties=await api.rpc('parties');for(const r of doc.recipients)if(r.party&&!parties.some(p=>p.id===r.party.id))parties.push(r.party);mode='edit';dirty=true;notice=t('Texto importado. Revise y retire encabezados o firmas anteriores; la plantilla generará los nuevos. El Word original se conserva.','Text imported. Review and remove previous headers or signatures; the template will generate new ones. The original Word is retained.');});return;}if(action==='download'){const file=doc.files.find(f=>f.id===id);await run(async()=>download(await api.download(file),file.filename));return;}
 if(action==='pdf'){await run(async()=>{const {recordsPdf}=await import('./records-pdf.js');const snapshot=doc.revisions?.[0]?.snapshot||doc;const pdf=recordsPdf({...snapshot,attachments:snapshot.attachments||doc.files.filter(f=>f.kind==='attachment')},{logo,lang,draft:!doc.sequence});download(new Blob([pdf.buffer],{type:'application/pdf'}),pdf.filename);});return;}
 if(action==='submit'){const missing=validateDocument(doc,{submit:true});if(missing.length){error=t('Complete el destinatario, el contenido y el firmante antes de remitir para firma. Use Continuar edición.','Complete the recipient, content and signer before submitting. Choose Continue editing.');draw();return;}}
 if(['submit','approve','register'].includes(action)){await run(async()=>{await api.rpc(action,doc.id,doc.version);if(action==='submit')draftCount=Math.max(0,draftCount-1);doc=await api.rpc('read',doc.id);notice=t('Estado actualizado.','Status updated.');});return;}
 if(!await leave())return;dirty=false;error='';notice='';op=null;
 await run(async()=>{
  if(action==='reply'){id=await api.rpc('reply',doc.id,doc.version,{lang});doc=await api.rpc('read',id);action=doc.author_id===profile.id?'edit':'open';if(action==='open')notice=t('Ya existe un borrador de respuesta. Su autor puede continuar la edición.','A reply draft already exists. Its author can continue editing.');}
  if(action==='resume'){doc=await api.rpc('read',id);action='edit';}
  if(action==='open'){doc=await api.rpc('read',id);direction=doc.direction;draft=null;mode='detail';}
  else if(['new','incoming','reply','edit'].includes(action)){const incoming=action==='incoming';writing=action==='edit';clearIntake();choosingSigner=false;pendingAttachments=[];if(action==='edit'){draft={...structuredClone(doc),recipients:doc.recipients.map(r=>({party_id:r.party.id,contact_id:r.contact_id,kind:r.kind}))};}else{if(action!=='reply')doc=null;draft={direction:incoming?'incoming':'outgoing',subject:action==='reply'?t('Respuesta: ','Reply: ')+doc.subject:'',document_date:day(),place:boot.sites.find(s=>s.id===boot.member?.site_id)?.name||'',body:'',classification:action==='reply'?doc.classification:'ordinary',signer_id:!incoming&&boot.signers.some(s=>s.id===profile.id)?profile.id:'',received_at_local:localDateTime(),received_at:new Date().toISOString(),channel:'email',parent_id:action==='reply'?doc.id:null,recipients:action==='reply'?doc.recipients.filter(r=>r.kind==='from').map(r=>({party_id:r.party.id,contact_id:r.contact_id,kind:'to'})):[{party_id:'',kind:incoming?'from':'to'}]};}parties=await api.rpc('parties');for(const r of doc?.recipients||[])if(r.party&&!parties.some(p=>p.id===r.party.id))parties.push(r.party);suppliers=await api.directory();direction=draft.direction;mode='edit';}
  else if(action==='party'){editing=null;partyBack=false;suppliers=await api.directory();mode='party';}
  else {if(['inbox','outbox'].includes(action)){if(mode!=='contacts')filterCache[direction]={q,status,offset,filters};direction=action==='inbox'?'incoming':'outgoing';({q='',status='',offset=0,filters={}}=filterCache[direction]||{});mode='documents';doc=null;}if(['documents','contacts'].includes(action)){mode=action;if(action==='documents')doc=null;}if(action==='cancel-edit')mode=doc?'detail':'documents';if(['drafts','all-outgoing'].includes(action)){direction='outgoing';mode='documents';doc=null;q='';status=action==='drafts'?'draft':'';filters={};offset=0;}if(action==='clear'){q='';status='';filters={};offset=0;}if(action==='next')offset+=50;else if(action==='prev')offset=Math.max(0,offset-50);else if(!['inbox','outbox','documents','cancel-edit'].includes(action))offset=0;draft=null;clearIntake();await refresh();}
 });
 }

 function signerField(d){const signer=boot.signers.find(s=>s.id===d.signer_id);return '<div class="records-auto records-signer"><strong>'+t('Persona que suscribe','Signatory')+'</strong><span>'+esc(signer?.name||t('Pendiente de asignar','Not assigned'))+(signer?.id===profile.id?' · '+t('Usted','You'):'')+'</span>'+(signer?.job_title?'<small>'+esc(signer.job_title)+'</small>':'')+(choosingSigner?select('signer_id',t('Seleccione la persona que suscribe','Select signatory'),opt('',t('Pendiente de asignar','Not assigned'),d.signer_id)+boot.signers.map(s=>opt(s.id,s.name,d.signer_id)).join('')):'<input type="hidden" name="signer_id" value="'+esc(d.signer_id||'')+'">')+b('change-signer',choosingSigner?t('Cerrar selección','Close selection'):signer?t('Cambiar persona que suscribe','Change signatory'):t('Asignar persona que suscribe','Assign signatory'))+(!signer?'<small>'+t('Puede guardar el borrador y asignar a una persona autorizada antes de remitirlo para firma.','Save the draft and assign an authorized signatory before submitting.')+'</small>':'')+'</div>';}
 function annexList(d){const files=recordAttachments(d);return files.length?'<section class="records-annex-list"><h3>'+t('Anexos','Attachments')+'</h3><ol>'+files.map(f=>'<li>'+esc(f.filename)+'</li>').join('')+'</ol></section>':'';}
 function annexEditor(d){return '<section class="records-wide records-intake records-letter-annex" data-letter-annex><h3>'+t('Anexos del oficio','Letter attachments')+'</h3><p class="records-help">'+(d.direction==='incoming'?t('Opcional. Cargue por separado los documentos que acompañan al oficio principal.','Optional. Upload the documents accompanying the main letter separately.'):t('Sus nombres se incorporan automáticamente después del nombre y cargo del firmante, en la vista previa y en el PDF.','Their names appear automatically after the signatory’s name and job title, in the preview and PDF.'))+'</p>'+annexList(d)+'<label>'+t('Seleccionar anexos PDF','Select PDF attachments')+'<input type="file" name="annex_files" accept=".pdf,application/pdf" multiple></label><small class="records-help">'+(d.direction==='incoming'?t('PDF · máximo 20 MB por archivo. Se incorporan al registrar la recepción.','PDF · maximum 20 MB per file. Uploaded when registering reception.'):t('Máximo 20 MB por archivo. Los archivos seleccionados se suben al guardar el borrador.','Maximum 20 MB per file. Selected files upload when the draft is saved.'))+'</small>'+pendingAttachments.map((f,i)=>'<div class="records-file"><span>'+esc(f.name)+'<small>'+t('Pendiente de guardar','Pending save')+' · '+Math.ceil(f.size/1024)+' KB</small></span>'+b('remove-pending-annex',t('Quitar','Remove'),false,'data-id="'+i+'"')+'</div>').join('')+'</section>';}

 function clearIntake(){if(intakePreview)URL.revokeObjectURL(intakePreview);intakeFile=null;intakePreview='';intakePages=0;intakeUploaded=false;}
 function intakeFields(){return `<section class="records-wide records-intake"><h3>${t('Oficio principal','Main letter')}</h3><label>${t('PDF del oficio principal *','Main letter PDF *')}<input type="file" name="intake_file" accept=".pdf,application/pdf"></label><p class="records-help">${t('PDF · máximo 20 MB. Incluya únicamente las páginas del oficio. Cargue sus anexos por separado debajo.','PDF · maximum 20 MB. Include only the letter pages. Upload attachments separately below.')}</p><details><summary>ⓘ ${t('Recomendaciones de escaneo','Scanning recommendations')}</summary><p class="records-help">${t('Escanee a 200–300 ppp. Use escala de grises, o color si es necesario para distinguir sellos u otros elementos. El archivo debe abrir sin contraseña.','Scan at 200–300 dpi. Use grayscale, or color when needed to distinguish stamps or other elements. The file must open without a password.')}</p></details>${intakeFile?'<p>'+esc(intakeFile.name)+' · '+Math.ceil(intakeFile.size/1024)+' KB · '+intakePages+' '+t('página(s)','page(s)')+'</p><a class="button secondary" href="'+intakePreview+'" target="_blank" rel="noopener">'+t('Vista previa del PDF','Preview PDF')+'</a>':draft.files?.some(f=>f.kind==='incoming')?'<p>'+t('PDF ya incorporado. Puede completar la recepción.','PDF already uploaded. You can complete reception.')+'</p>':''}<p class="records-help">${t('El número GLF se asigna al completar el registro del oficio y sus anexos seleccionados.','The GLF number is assigned after registering the letter and its selected attachments.')}</p></section>`;}

 function fileRow(f,label){return '<div class="records-file"><span>'+esc(label||f.filename)+'<small>'+esc(f.filename)+' · '+Math.ceil(f.size/1024)+' KB</small></span>'+b('download',t('Descargar','Download'),false,'data-id="'+f.id+'"')+'</div>';}
 function mainLetterView(d){const main=latestMainFile(d),previous=d.files.filter(f=>f.kind==='incoming'&&f.id!==main?.id);return '<p class="records-subject"><strong>'+t('Asunto: ','Subject: ')+esc(d.subject)+'</strong></p><section class="records-main-file"><h3>'+t('Oficio principal','Main letter')+'</h3>'+(main?b('view-main',t('Ver oficio','View letter'),true,'data-id="'+main.id+'"')+fileRow(main,t('Versión vigente del oficio','Current letter version')):'<p>'+t('Pendiente de incorporar el PDF principal.','Main PDF not yet uploaded.')+'</p>')+(previous.length?'<details><summary>'+t('Versiones anteriores del oficio','Previous letter versions')+' ('+previous.length+')</summary>'+previous.map(f=>fileRow(f)).join('')+'</details>':'')+'</section>';}
 function followupView(d){const incoming=d.direction==='incoming',events=d.followup||[],last=events.find(e=>e.action==='directive'),active=['received','assigned'].includes(d.status);return (incoming?'<h2>'+t('Seguimiento y disposiciones','Follow-up and instructions')+'</h2><div class="records-tracking-summary"><div><small>'+t('Responsable actual','Current owner')+'</small><strong>'+esc(d.assigned_name||t('Pendiente de asignar','Unassigned'))+'</strong></div><div><small>'+t('Situación de la atención','Progress')+'</small><strong>'+esc(attentionStatus(d,lang))+'</strong></div><div><small>'+t('Plazo','Due date')+'</small><strong>'+esc(d.due_date||t('Sin plazo definido','No deadline'))+(overdue(d)?' · '+t('Vencido','Overdue'):'')+'</strong></div></div>'+(last?'<p class="records-last-instruction"><strong>'+t('Última disposición: ','Latest instruction: ')+'</strong>'+esc(last.detail)+'</p>':'')+'<div class="records-actions">'+(active&&can('assign')?b('assign',t('Asignar o reasignar','Assign or reassign'))+b('directive',t('Registrar disposición','Record instruction')):'')+(active&&(can('assign')||d.assigned_to===profile.id)?b('attention',t('Registrar atención','Record action taken')):'')+'</div>'+operationView()+'<ol class="records-timeline">'+events.map(e=>'<li><strong>'+esc(e.related_id&&followupLabels[e.action]?followupLabels[e.action][lang==='es'?0:1]:eventLabel(e.action))+'</strong>'+(e.target_name?'<span> → '+esc(e.target_name)+'</span>':'')+(e.detail?'<p>'+esc(e.detail)+'</p>':'')+(e.due_date?'<p>'+t('Plazo: ','Due: ')+esc(e.due_date)+'</p>':'')+(e.evidence_file_id?b('download',t('Ver documento de respaldo','Download supporting file'),false,'data-id="'+e.evidence_file_id+'"'):'')+(e.related_id?b('open',t('Abrir respuesta','Open reply'),false,'data-id="'+e.related_id+'"'):'')+'<small>'+esc(e.actor_name)+' · '+esc(fmt(e.created_at))+'</small></li>').join('')+'</ol>'+(!events.length?'<p>'+t('Todavía no se han registrado actuaciones.','No actions recorded yet.')+'</p>':''):'<h2>'+t('Seguimiento','Follow-up')+'</h2>')+'<details class="records-technical"><summary>'+t('Registro técnico de cambios','Technical change log')+'</summary>'+d.events.map(e=>'<div class="records-event">'+esc(eventLabel(e.action))+'<small>'+esc(e.actor_name)+' · '+fmt(e.created_at)+'</small>'+(e.detail?'<p>'+esc(e.detail)+'</p>':'')+'</div>').join('')+'</details>';}

 function relatedView(){return doc.related?.length?'<h3>'+t('Correspondencia relacionada','Related correspondence')+'</h3>'+doc.related.map(r=>'<div class="records-related">'+b('open',number(r)+' · '+r.subject,false,'data-id="'+r.id+'"')+'<small>'+esc(recordStatus(r.status,r.direction,lang))+'</small></div>').join(''):'';}
 function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}
 return {canLeave:leave,async mount(el,language,account,{admin=false}={}){if(draft)collect();root=el;lang=language;profile=account;if(admin)mode='admin';if(!api)api=await createRecordsStore(baseStore);await run(refresh);},reset(){closePreview();view='all';total=0;returnView=null;restoreScroll=null;clearIntake();pendingAttachments=[];choosingSigner=false;direction='incoming';filters={};filterCache={};boot=null;doc=null;draft=null;dirty=false;mode='documents';adminData=null;editing=null;}};
}
